ids = ["LY-242","LY-243","LY-244","LY-245","LY-246","LY-249","LY-250","LY-251","LY-252","LY-253","LY-254","LY-255","LY-259","LY-301","LY-304","LY-305","LY-306","LY-307","LY-309","LY-311"]
assert set(PREDS.keys()) == set(ids), "id set mismatch"
assert len(PREDS) == len(ids) == 20

for cid in ids:
    p = PREDS[cid]
    rec = {"case_id": cid, "prediction_text": p["prediction_text"], "basis": p["basis"],
           "confidence": p["confidence"], "trigger": p["trigger"]}
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)

# readback verification
count = 0
for cid in ids:
    path = os.path.join(OUT, cid + ".json")
    with open(path, encoding="utf-8") as f:
        rec = json.load(f)
    assert rec["case_id"] == cid, cid
    for field in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
        assert field in rec and rec[field] not in (None, ""), (cid, field)
    assert isinstance(rec["confidence"], (int, float)) and 0 <= rec["confidence"] <= 1, cid
    tr = rec["trigger"]
    for b in ("changed_main", "reserve_used", "disputed"):
        assert isinstance(tr[b], bool), (cid, b)
    assert isinstance(tr["reason"], str), cid
    count += 1
assert count == len(ids) == 20
cm = sum(1 for c in ids if PREDS[c]["trigger"]["changed_main"])
ru = sum(1 for c in ids if PREDS[c]["trigger"]["reserve_used"])
di = sum(1 for c in ids if PREDS[c]["trigger"]["disputed"])
print(f"WROTE_AND_VERIFIED {count} files; changed_main={cm} reserve_used={ru} disputed={di}")
